(()=>{var SELF_UPDATE_ALARM="self-update-check";function compareVersions(a,b){let pa=String(a||"").split(".").map(x=>parseInt(x,10)||0),pb=String(b||"").split(".").map(x=>parseInt(x,10)||0);for(let i=0;i<Math.max(pa.length,pb.length);i++){let d=(pa[i]||0)-(pb[i]||0);if(d)return d}return 0}async function extensionPageInFront(){try{let active=await chrome.tabs.query({active:!0,lastFocusedWindow:!0});if(chrome.runtime.getContexts){let ctx=await chrome.runtime.getContexts({contextTypes:["TAB","POPUP"]});if(ctx.some(c=>c.contextType==="POPUP"))return!0;let ids=new Set(active.map(t=>t.id));return ctx.some(c=>ids.has(c.tabId))}let origin=chrome.runtime.getURL("");return active.some(t=>String(t.url||t.pendingUrl||"").startsWith(origin))}catch{return!1}}async function checkForNewVersion(deps={}){let running=chrome.runtime.getManifest();if(running.update_url)return{action:"store",running:running.version};let onDisk="";try{let read=deps.fetchManifest||(async()=>(await fetch(chrome.runtime.getURL("manifest.json"),{cache:"no-store"})).json());onDisk=String((await read()).version||"")}catch(e){return{action:"error",running:running.version,error:String(e?.message||e)}}return!onDisk||compareVersions(onDisk,running.version)<=0?{action:"same",running:running.version,onDisk}:await(deps.inFront||extensionPageInFront)()?{action:"busy",running:running.version,onDisk}:(await chrome.storage.local.set({selfUpdateLast:{at:Date.now(),from:running.version,to:onDisk}}),(deps.reload||(()=>chrome.runtime.reload()))(),{action:"reload",running:running.version,onDisk})}function scheduleSelfUpdateCheck(){chrome.alarms.create(SELF_UPDATE_ALARM,{periodInMinutes:2})}globalThis.__nlsSelfUpdate={SELF_UPDATE_ALARM,checkForNewVersion,scheduleSelfUpdateCheck};})();
